    // 1/4 波对称查找表 + 线性插值
    // 只存 sin 在 [0, pi/2] 的 17 个采样点（步长 pi/32，与全波 64 点表相同），
    // 其余象限由对称性导出：精度不变，但表存储/复用面积约为原来的 1/4。
    // z 的补码位型即全波相位（theta = z*pi/2^15）
    wire [15:0] phase = z;
    wire [5:0]  pidx  = phase[15:10];       // 全波相位索引 0..63
    wire [1:0]  quad  = pidx[5:4];          // 象限 0..3
    wire [3:0]  ridx  = pidx[3:0];          // 象限内索引 0..15
    wire [7:0]  frac  = phase[9:2];         // 相位小数（1/256 步长）

    // 线性插值：out = a + (b-a)*frac/256
    // 结果恒落在 a、b 之间，不会有 16-bit 溢出
    function signed [15:0] interp;
        input signed [15:0] a;
        input signed [15:0] b;
        input        [7:0]  f;
        reg   signed [31:0] pr;
        begin
            pr = (b - a) * $signed({1'b0, f});
            interp = a + (pr >>> 8);
        end
    endfunction

    // 1/4 波表：qt[i] = round(32767*sin(i*pi/32)), i = 0..16
    function signed [15:0] qt;
        input [4:0] i;
        begin
            case (i)
            5'd0:  qt = 16'sd0;
            5'd1:  qt = 16'sd3212;
            5'd2:  qt = 16'sd6393;
            5'd3:  qt = 16'sd9512;
            5'd4:  qt = 16'sd12540;
            5'd5:  qt = 16'sd15447;
            5'd6:  qt = 16'sd18205;
            5'd7:  qt = 16'sd20788;
            5'd8:  qt = 16'sd23170;
            5'd9:  qt = 16'sd25330;
            5'd10: qt = 16'sd27246;
            5'd11: qt = 16'sd28899;
            5'd12: qt = 16'sd30274;
            5'd13: qt = 16'sd31357;
            5'd14: qt = 16'sd32138;
            5'd15: qt = 16'sd32610;
            5'd16: qt = 16'sd32767;
            default: qt = 16'sd0;
            endcase
        end
    endfunction

    // x = (ridx + frac/256)*pi/32，S = sin(x)，C = cos(x)
    wire signed [15:0] s_q = interp(qt({1'b0, ridx}),         qt({1'b0, ridx} + 5'd1), frac);
    wire signed [15:0] c_q = interp(qt(5'd16 - {1'b0, ridx}), qt(5'd15 - {1'b0, ridx}), frac);

    // 象限映射：sin/cos 互为 S/C，并按象限取符号
    wire signed [15:0] base_sin = quad[0] ? c_q : s_q;
    wire signed [15:0] base_cos = quad[0] ? s_q : c_q;
    wire               sin_neg  = quad[1];
    wire               cos_neg  = quad[1] ^ quad[0];

    assign in_ready = !out_valid || out_ready;

    always @(posedge clk) begin
        if (!rst_n) begin
            out_valid <= 1'b0;
            sin_out   <= 16'sd0;
            cos_out   <= 16'sd0;
        end else begin
            if (in_valid && in_ready) begin
                sin_out   <= sin_neg ? -base_sin : base_sin;
                cos_out   <= cos_neg ? -base_cos : base_cos;
                out_valid <= 1'b1;
            end else if (out_valid && out_ready) begin
                out_valid <= 1'b0;
            end
        end
    end
    // EVOLVE-BLOCK-END

endmodule

